<script>

 var checkInSelected = false;
 var checkOutSelected = false;

function toisodate (thisdate){
 var mm = thisdate.getMonth() + 1; // getMonth() is zero-based
 var dd = thisdate.getDate();

 return [thisdate.getFullYear(),
 '-'+(mm>9 ? '' : '0') +mm,
 '-'+(dd>9 ? '' : '0') + dd
 ].join('');
};

mind= new Date();
mind.setDate(mind.getDate() -1);
maxd = new Date();
maxd.setDate(maxd.getDate() +365);

new Litepicker({
 element: document.getElementById('datepickertd'),

 singleMode: false,

 lang:"EN",
 format: "DD MMMM YYYY",

numberOfMonths: 2,
numberOfColumns: 2,
elementEnd: document.getElementById('datepicker2td'),

minDate: mind,
maxDate: maxd,
 tooltipText: {
 one: 'night',
 other: 'nights'
 },
 plugins: ['mobilefriendly'],
 tooltipNumber: (totalDays) => {
 return totalDays - 1;
 },

 setup: (picker) => {

 picker.on('preselect', (date1, date2) => {
 // some action
//alert (isEndDateSelected);
document.getElementById("datepickertd").style.backgroundColor = "#ffffff";
document.getElementById("datepicker").value = date1.toDateString();
document.getElementById("datevalue1").value = toisodate(date1);
document.getElementById("datepicker2td").style.backgroundColor = "#cee8f0";

 addCustomText();

}

);

 picker.on('show', (el) => {
 // some action
document.getElementById("datepickertd").style.backgroundColor = "#cee8f0";
 });

 picker.on('render', (ui) => {
 // some action after render
 // ui is root element of picker
 addCustomText();
 });

 
 picker.on('selected', (date1, date2) => {
 // some action toisodate(date2); date1.toDateString()
document.getElementById("datepicker2td").style.backgroundColor = "#ffffff";
 document.getElementById("datevalue1").value = toisodate(date1);
document.getElementById("datepicker").value = date1.toDateString();
document.getElementById("datevalue2").value = toisodate(date2);
document.getElementById("datepicker2").value = date2.toDateString();
$('html, body').animate({
 scrollTop: $('#table-container').offset().top
}, 'slow');
loadrates();


 });

 picker.on('change:month', (date, calendarIdx) => {
 // some action
 addCustomText()
 });


},


});

 function addCustomText() {
 const litepicker = document.querySelector('.month-item');
 let customTextContainer = litepicker.querySelector('.custom-text-container');
 const isStartDateSelected = document.querySelector('.day-item.is-start-date') != null;
 const isEndDateSelected = document.querySelector('.day-item.is-end-date') != null;

 if (!customTextContainer) {
 customTextContainer = document.createElement('div');
 customTextContainer.classList.add('custom-text-container');
 litepicker.appendChild(customTextContainer);
 }

 var d1 = new Date(document.getElementById('datevalue1').value); var d2 = new Date(document.getElementById('datevalue2').value);
 var d1val = document.getElementById('datevalue1').value; var d2val = document.getElementById('datevalue2').value;
 if (!checkInSelected)
 checkInSelected = isStartDateSelected;
 checkOutSelected = isEndDateSelected;

 let checkinDate = checkInSelected ? d1val : "Check In";
 let checkoutDate = checkOutSelected ? d2val : "Check Out";
 let checkInTextWeight = !checkInSelected ? "bold" : "normal";
 let checkOutTextWeight = checkInSelected && checkoutDate == "Check Out" ? "bold" : "normal";
 customTextContainer.innerHTML = `<span id="check-in-text" class="light-text" style="font-weight: ${checkInTextWeight}">${checkinDate}</span> - <span id="check-out-text" style="font-weight: ${checkOutTextWeight}">${checkoutDate}</span>`;

 // Style adjustments
 customTextContainer.style.textAlign = 'center';
 customTextContainer.style.padding = '10px 0';
 customTextContainer.style.backgroundColor = 'white';
 customTextContainer.style.zIndex = '1000';
 }



