<script>
function scrollChips(direction, e) {
  if (e) e.preventDefault(); // stop focus or text selection
  const container = document.getElementById('chipScroll');
  if (!container) return;

  // Blur any focused chip (prevents selection jump)
  if (document.activeElement && container.contains(document.activeElement)) {
    document.activeElement.blur();
  }

  // Scroll amount (tweak as you like)
  const amount = 150 * direction;
  container.scrollBy({ left: amount, behavior: 'smooth' });
}
</script>
